uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_z;
uniform float amzp_complexity;
uniform float amzp_density;
uniform float amzp_sceneswitchspeed;
uniform float amzp_EBLUR;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.0)*amzLayerToScreen()).xy; }
         const int2 samples = int2(3,3);
         float4 hash42(float2 p)
         {
          float4 p4 = fract(float4(p.xyxy) * float4(.1031, .1030, .0973, .1099));
             p4 += dot(p4, p4.wzxy+33.33);
             return fract((p4.xxyz+p4.yzzw)*p4.zywx);
         }
         float4 tex(float2 C) {
             float2 iResolution = float2(screen.zw.x, screen.zw.y);
             float iTime = (amzp_autop>0.5)? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS;
             float2 R = iResolution.xy;
                 float4 o2 = float4(1);
                 float2 uv = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
                 uv.y *=layer.y/layer.x;
                 uv /= amzp_scale;
                 uv *= rot2m((0.0+amzp_angle)*0.0174533);
                 uv += float2((-250.0+amzp_position.x), (250.0+amzp_position.y))*float2(-1.,1.0)/500.0;
                 float2 scaleVec;
                 scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
                 uv /= scaleVec;
                 float t = iTime;
                 t+=1e2;
                 float4 h = hash42(floor(uv) + floor(1.0*amzp_sceneswitchspeed));
                 uv.y += uv.x*(h.x-.5);
                 uv.x *= R.x/R.y;
                 uv *= amzp_z;
                 uv += floor(t*amzp_sceneswitchspeed)*amzp_z*h.y;
                 float s = 1.0;
                 for (float i = 1.0;i <= amzp_complexity; ++ i) {
                     float2 c = floor(uv+i);
                     float4 h = hash42(c);
                     float2 p = fract(uv+i+(floor((t)/(h.z+1.0))*(h.z+1.0))*h.y);
                     uv+= p*h.z*h.xy*float2(s,2.0);
                     s = -s*(1.1+h.y);
                     if (h.w > amzp_density) {
                         o2 *= h;
                     }
                 }
             o2 = step(.5,o2);
             return o2;
         }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float3 iMouse = float3(0.5, 0.5, 0.5);
        float iTime = (amzp_autop>0.5)? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.0)/500.0;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 o;
             float2 R = iResolution.xy;
             float2 C = float4(amzCoord.x/1.0,(screen.w-amzCoord.y)/1.0,0.0,1.0).xy;
             float2 uv = satriyaid;
                 float4 o2 = float4(1.0);
                 float2 N = uv- 0.5;
             if((amzp_EBLUR>0.5)) {
             o = float4(0.0);
             float accum = 0.0;
             for (int x = -samples.x; x < samples.x; ++x) {
                 float2 offset = float2(x,0);
                 float weight = abs(float(samples.x) - float(x));
                 o += tex(C + offset) * weight;
                 accum += weight;
             }
             for (int y = -samples.y; y < samples.y; ++y) {
                 float2 offset = float2(0, y);
                 float weight = abs(float(samples.y) - float(y));
                 o += tex(C + offset) * weight;
                 accum += weight;
             }
             o /= accum;
             }
             o = tex(C);
             o=smoothstep(.2,.8,o) * mod(C.x,3.0)/2.5;
             o=clamp(o,0.,1.0);
            o = pow(o,o-o+.5);
         float4 factor = mix(texColorX,o,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) { resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.0)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness; resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
